def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的地形剖面、海岸作用與證據判讀能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的高度、坡度、剖面、岩性、波浪、沉積與時間資料。", f"整理證據：把觀察到的地形形態和形成作用分開；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」能同時符合題幹的地形證據與作用機制。", "排除誘答：檢查是否只看用途、單張照片或單一岸段，或把侵蝕與沉積誤當成互斥現象。", "結論回查：回到剖面圖、地圖與時間資料確認；換岸段或尺度後不能直接沿用原結論。"]
    return {"id": f"question-social-content-geo-ab-iv-1-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-ab-iv-1"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫地形與海岸分類情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-ab-iv-1", "examPatternRefs": refs, "solutionStrategy": "先從剖面、坡度、岩性與海岸形態辨識地形，再連結侵蝕、搬運、沉積與人類利用，最後檢查證據尺度。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-ab-iv-1-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
